    diagram: {"kind":"pictograph","title":"Seedlings still alive after 4 weeks","icon":"tree","keyValue":2,"keyNoun":"seedlings","rows":[{"label":"Fresh water","count":9},{"label":"Slightly salty","count":6.5},{"label":"Salty","count":3},{"label":"Very salty","count":0.5}]},
