    year_level: 'year_10',
    difficulty: 'proficient',
    diagram: {"kind":"data_table","title":"CO₂ in air trapped in ice at Law Dome, Antarctica","columns":["Year the air was trapped","CO₂ (ppm)"],"rows":[["1000",279],["1500",282],["1800",284],["1900",296],["1950",311],["1980",338]]},
